INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (48, 403, 'BOPP Metallized film aluminium silver', '../upload/image/20211215/20211215203711_18066.jpg', '<p><span class="nownavi" style="font-family:Tahoma;"><strong><span class="nownavi"><span style="font-size:18px;color:#009900;">BOPP Metallized film aluminium silver</span><br/> </span></strong></span></p> <div style="font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> <strong><span style="font-size:18px;color:#009900;font-family:Tahoma;">BOPP (</span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;">Polypropylene)</span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;">aluminum&nbsp;</span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;">metallized film (silver)</span> </strong> </div> <div style="font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> <strong><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Thickness : 15,18,20,25,30,35 Microns</strong></span><br/> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Width : 350-1500MM</strong></span><br/> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Length :5000-12000M</strong></span><strong>&nbsp;</strong><br/> <div> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Color : silver&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>aluminum&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>metallized</strong></span> </div> <div> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Package : Standard exporting package with pallets .</strong></span><br/> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Application : lamination &amp; printing and so forth.</strong></span> </div> <div> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Usgae: food packing or others packing.</strong></span> </div> </strong> </div> <div style="font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> <strong><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Future:&nbsp; inner side corona treatment and&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>aluminum&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>metallized, outer&nbsp;</strong></span><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>side heat sealable, ( basic BOPP is two sides heat sealable BOPP）</strong></span> </strong> </div> <strong> <p></p> <div style="font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>or&nbsp;</strong></span><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>outer side corona treatment and&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>aluminum&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>metallized, and inner&nbsp;</strong></span><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>side heat sealable, ( basic BOPP is two sides heat sealable BOPP）</strong></span> </div> </strong> <p><br/></p> <div style="color:#000000;font-family:Calibri;font-size:19px;font-style:normal;font-weight:400;text-align:start;background-color:#FFFFFF;"> <br/> </div> <br/> <p><br/></p> <p><span class="nownavi"><br/> </span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (48, 246, 'BOPP tape grade film', '../upload/image/20180826/20180826191402_20626.jpg', '<p><span style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style="font-family:Tahoma;font-size:18px;"><span arial="" geneva="" helvetica="" new="" roman="" sans-serif="" style="white-space: normal; color: rgb(58, 58, 58);" times="" verdana=""><span style="font-size:18px;color:#009900;">BOPP tape grade film clear jumbo roll</span></span><br/> <br/> <span style="color:#009900;font-size:18px;background-color:#FFFFFF;">This goods is used for manufacturing BOPP adhesive packing tape (jumbo roll size). Also for high quality tape uses .</span><br/> <span arial="" geneva="" helvetica="" new="" roman="" sans-serif="" style="white-space: normal; color: rgb(58, 58, 58);" times="" verdana=""><span style="font-size:18px;color:#009900;">Specifications:</span></span><br/> <span arial="" geneva="" helvetica="" new="" roman="" sans-serif="" style="white-space: normal; color: rgb(58, 58, 58);" times="" verdana=""><span style="font-size:18px;color:#009900;">1) Length: 4000, 4850, 6000m..</span></span><br/> <span arial="" geneva="" helvetica="" new="" roman="" sans-serif="" style="white-space: normal; color: rgb(58, 58, 58);" times="" verdana=""><span style="font-size:18px;color:#009900;">2) Width: 500mm, 520mm, 980mm,1000mm, 1040mm, 1200mm, 1280mm, 1310mm,1600mm,1620,1800, 2000mm etc.</span></span><br/> <span style="color:#009900;font-size:18px;background-color:#FFFFFF;">3) Color: Transparence</span><br/> <span arial="" geneva="" helvetica="" new="" roman="" sans-serif="" style="white-space: normal; color: rgb(58, 58, 58);" times="" verdana=""><span style="font-size:18px;"><span style="color:#009900;">4) Thickness: 18,20,23,25,28,30,35</span><span style="color:#009900;"> microns and others</span></span></span><br/> <span arial="" geneva="" helvetica="" new="" roman="" sans-serif="" style="white-space: normal; color: rgb(58, 58, 58);" times="" verdana=""><span style="font-size:18px;color:#009900;">5) Packing: Using carton with pallets or as per customers'' requirements</span></span><br/> <span style="color:#009900;font-size:18px;background-color:#FFFFFF;">6) used to adhere water based acrylic liquid and manufactured as Bopp packing tape.</span></span></span></p>', '2026-09-06 20:58:45');
